triggered := false
if (triggered == true) {
wait until(not (#Main_Valve).valve_valveState)
    triggered = false
}
wait until((#Main_Valve).valve_valveState)
triggered = true
hold_ticks := 0
fired := false
if ((#Main_Valve).valve_valveState == false) {
if (fired == false) {
hold_ticks = hold_ticks + 1
        if (hold_ticks >= 600) {
(#Main_Valve).valve_close()
(#Kitchen_Speaker).speaker_speak("The water valve has been closed")
            fired = true
}
}
}
else {
hold_ticks = 0
    fired = false
}

